"use client";

import { AuthGuard } from "@/components/auth/AuthGuard";
import { LobbyHeader } from "@/components/lobby/LobbyHeader";
import { useLobbyLogout } from "@/hooks/useLobbyLogout";
import { useMeQuery } from "@/store/api/authApi";
import { useGetRateQuery } from "@/store/api/paymentsApi";

export default function DepositPage() {
  return (
    <AuthGuard>
      <DepositStub />
    </AuthGuard>
  );
}

/** Temporary shell so Deposit nav works; full form comes next from deposit mockup. */
function DepositStub() {
  const onLogout = useLobbyLogout();
  const { data: me } = useMeQuery();
  const { data: rateData } = useGetRateQuery();

  return (
    <div className="min-h-screen w-full bg-[#01100b] text-[#f5efe0]">
      <LobbyHeader
        active="deposit"
        balanceUsd={me?.balance?.realBalance ?? "0"}
        mmkPerUsd={rateData?.mmkPerUsd ?? "4500"}
        onLogout={onLogout}
      />
      <main className="w-full px-3 py-10 sm:px-4 lg:px-5">
        <h1 className="text-[1.45rem] font-bold text-white">Deposit Funds</h1>
        <div className="mt-2 h-px w-40 bg-[#d4af37]/70" />
        <p className="mt-4 text-[0.95rem] text-[#9a9280]">
          Deposit form UI coming next (mockup ready).
        </p>
      </main>
    </div>
  );
}
